    s = await waitSettled(h);
    assert.equal(s.input, "何琳", "相同负责人分派期间的草稿同样保留");
    assert.match(s.notice.text, /提交的负责人与当前负责人相同，负责人未变化，仍为：高翔/);
    assert.match(s.notice.text, /输入框中的当前内容尚未提交/);
    assert.equal(s.fields["负责人"], "高翔");
